import type { Lesson, StudyVisual } from './content';

type Seed = {
  id: string; path: string; title: string; brief: string; concept: string;
  command: string; meaning: string; output: string; flow: [string, string, string];
  quiz: [string, string, string, string, number]; tags: string[];
  notes: [string, string, string]; visual?: StudyVisual; caution?: string;
};

const B = (s: Seed): Lesson => ({
  id: s.id, path: s.path, title: s.title, eyebrow: 'Углублённая теория', minutes: 13,
  brief: s.brief, concept: s.concept, command: s.command,
  commandMeaning: s.meaning, output: s.output, flow: s.flow,
  question: s.quiz[0], answers: [s.quiz[1], s.quiz[2], s.quiz[3]], correct: s.quiz[4],
  tags: s.tags, caution: s.caution, visual: s.visual,
  details: [
    { title: 'Как устроено', text: s.notes[0] },
    { title: 'Что наблюдать', text: s.notes[1] },
    { title: 'Граница вывода', text: s.notes[2] },
  ],
});

export const bookLessons: Lesson[] = [
  B({ id:'ethernet-mac', path:'traffic', title:'Кадр Ethernet и MAC-адрес', brief:'Пойми, как пакет добирается до соседнего устройства.', concept:'IP-адрес отвечает за доставку между сетями, а MAC-адрес — за доставку кадра в локальном сегменте. При переходе через маршрутизатор IP-назначение обычно остаётся тем же, а MAC-адреса кадра меняются на каждом канальном участке. Поэтому захват на разных участках покажет разные Ethernet-заголовки.', command:'ip link show', meaning:'Посмотреть интерфейсы и их канальные адреса на своей машине.', output:'link/ether 02:42:ac:11:00:02', flow:['IP-пакет','Ethernet-кадр','Соседний узел'], quiz:['Что меняется при переходе через маршрутизатор?','MAC-адреса кадра','Адрес назначения IP всегда','Порт приложения всегда',0], tags:['ethernet','mac','кадр','wireshark'], notes:['Кадр содержит MAC отправителя, MAC получателя, тип полезной нагрузки и контрольную сумму. Он существует в пределах канального сегмента.','Сравни адрес интерфейса с адресом следующего перехода. В анализаторе пакетов отделяй Ethernet-заголовок от вложенного IP-заголовка.','MAC-адрес не равен идентичности человека или сервиса: его можно изменить, а маршрутизатор создаёт новый кадр для следующего участка.'], visual:{title:'Один IP-пакет, несколько кадров',kind:'sequence',items:[{label:'Хост A',detail:'MAC A → MAC шлюза'},{label:'Маршрутизатор',detail:'Извлекает IP-пакет и выбирает путь'},{label:'Хост B',detail:'Новый MAC-кадр на последнем участке'}]} }),
  B({ id:'arp', path:'traffic', title:'ARP: кто владеет адресом?', brief:'Разбери таблицу соседей и признаки подмены соответствия IP↔MAC.', concept:'Перед отправкой IPv4-пакета соседу узел узнаёт MAC-адрес по IP через ARP. Результат некоторое время живёт в таблице соседей. Подмена ARP-ответа может направить локальный трафик через чужое устройство; само наличие нового адреса ещё не доказывает атаку — нужны дополнительные наблюдения.', command:'ip neigh show', meaning:'Показать известные соответствия IP и MAC на собственной машине.', output:'192.0.2.1 dev eth0 lladdr 02:42:ac:11:00:01 REACHABLE', flow:['IP соседа','ARP-запрос и ответ','Запись IP↔MAC'], quiz:['Что хранит ARP-таблица?','Пары IP и MAC соседей','Пароли пользователей','Сертификаты TLS',0], tags:['arp','spoofing','mac','таблица соседей'], notes:['ARP работает только в локальном канальном сегменте. Для удалённой сети узел ищет MAC следующего перехода, обычно шлюза.','Для анализа сравни записи на нескольких хостах и журнал изменений. Резкая смена MAC шлюза в стабильной сети — повод проверить инфраструктуру.','Динамические записи могут легитимно меняться из-за переезда ВМ, отказоустойчивости и замены оборудования. Контекст сети важен.'], visual:{title:'Разрешение адреса внутри сегмента',kind:'sequence',items:[{label:'Хост',detail:'Кому принадлежит 192.0.2.1?'},{label:'Сосед',detail:'Ответ: мой MAC 02:42:…'},{label:'Кэш ARP',detail:'Пара используется для отправки кадра'}]} }),
  B({ id:'packet-layers', path:'traffic', title:'Анатомия сетевого пакета', brief:'Научись читать вложенные заголовки от канального уровня до приложения.', concept:'Трафик удобно рассматривать как вложенные оболочки: Ethernet несёт IP, IP несёт TCP/UDP, транспорт несёт данные приложения. Каждый заголовок отвечает на отдельный вопрос: куда передать следующий кадр, какой узел и сервис получит пакет, как приложение интерпретирует данные.', command:'sudo tcpdump -i lo -nn -c 5', meaning:'Захватить пять пакетов только на локальном интерфейсе своей машины.', output:'IP 127.0.0.1.50000 > 127.0.0.1.8000: Flags [S]', flow:['Кадр','IP + TCP/UDP','Данные приложения'], quiz:['Какой уровень содержит номер порта?','Транспортный','Канальный','Физический',0], tags:['tcpdump','wireshark','пакет','стек'], notes:['Инкапсуляция добавляет заголовки при отправке, а принимающая сторона снимает их в обратном порядке. Поля каждого уровня имеют свою область действия.','В анализаторе раскрывай уровни по очереди; отмечай адреса, порты, флаги и полезную нагрузку. Выбирай фильтр захвата отдельно от фильтра отображения.','Зашифрованный HTTPS не раскрывает содержимое HTTP в обычном pcap, но метаданные соединения часто остаются видимыми.'], visual:{title:'Вложенность уровней',kind:'layers',items:[{label:'Приложение',detail:'HTTP, DNS, SSH: смысл данных'},{label:'Транспорт',detail:'TCP/UDP: порт, доставка, состояние'},{label:'Сеть',detail:'IP: узел назначения и маршрут'},{label:'Канал',detail:'Ethernet: следующий сосед в сегменте'}]} }),
  B({ id:'tcp-handshake', path:'traffic', title:'TCP: рукопожатие и состояние', brief:'Объясни SYN, SYN-ACK, ACK и почему порт открыт или закрыт.', concept:'TCP сначала согласует соединение трёхшаговым рукопожатием: SYN, SYN-ACK, ACK. Затем обе стороны передают байтовый поток, подтверждают получение и управляют окном. Сканер делает вывод о состоянии порта по наблюдаемым ответам, но firewall и потери пакетов могут менять картину.', command:'ss -tan | head', meaning:'Посмотреть TCP-соединения и их состояния на своей машине.', output:'ESTAB 0 0 192.0.2.10:50120 192.0.2.20:443', flow:['SYN','SYN-ACK','ACK → ESTABLISHED'], quiz:['Какой порядок у обычного TCP-рукопожатия?','SYN → SYN-ACK → ACK','ACK → SYN → FIN','FIN → ACK → SYN',0], tags:['tcp','handshake','syn','порт'], notes:['SYN сообщает начальные параметры и предложение соединения. SYN-ACK подтверждает запрос и отправляет встречное предложение. ACK завершает согласование.','Сопоставляй флаги и номера последовательности в pcap. Повторные передачи могут говорить о потерях, фильтрации или перегрузке, а не об одной конкретной причине.','Состояние ESTABLISHED означает установленный TCP-канал, но не доказывает успешную авторизацию или корректную работу приложения.'], visual:{title:'Диалог двух узлов',kind:'sequence',items:[{label:'Клиент → сервер',detail:'SYN: хочу соединиться'},{label:'Сервер → клиент',detail:'SYN-ACK: готов, подтверждаю'},{label:'Клиент → сервер',detail:'ACK: параметры согласованы'}]} }),
  B({ id:'wireshark', path:'traffic', title:'Wireshark: читать, а не гадать', brief:'Фильтры, последовательности и доказательства из pcap.', concept:'Wireshark разделяет захват и анализ: сначала нужно получить пакеты в разрешённом сегменте, затем отфильтровать интересующий разговор. Фильтры отображения не удаляют данные из pcap. В отчёте сохраняйте время, узлы, протокол и объяснение, почему пакет подтверждает конкретный вывод.', command:'tcpdump -r lab.pcap -nn | head', meaning:'Посмотреть начало ранее собранного учебного pcap без нового захвата.', output:'12:00:00 IP 192.0.2.10.50000 > 192.0.2.20.443', flow:['Файл pcap','Фильтр и разговор','Подтверждённый факт'], quiz:['Меняет ли display filter исходный pcap?','Нет','Да, удаляет пакеты','Да, шифрует его',0], tags:['wireshark','pcap','filter','tcpdump'], notes:['Фильтр захвата выбирает, что попадёт в файл, и применяется до сохранения. Фильтр отображения выбирает, что показывать из уже собранного.','Начинай с общего обзора протоколов и потоков, затем сужайся до адреса, порта и времени. Сравни запрос и ответ, ищи повторы и ошибки.','Захват может содержать токены, содержимое сессий и личные данные. Минимизируй объём и храни файл как чувствительный материал.'] }),
  B({ id:'sockets', path:'traffic', title:'Сокеты и граница процесса', brief:'Как приложение превращает адрес и порт в обмен данными.', concept:'Сокет — интерфейс приложения к сетевому стеку. Сервер создаёт сокет, привязывает его к адресу и порту, начинает слушать; клиент подключается к нему. TCP-соединение определяется парой конечных точек, поэтому один слушающий порт может обслуживать много клиентов одновременно.', command:'ss -lntp', meaning:'Показать слушающие TCP-сокеты и процессы на собственной машине.', output:'LISTEN 0 128 127.0.0.1:8000 users:(("python3",pid=1234))', flow:['Процесс','Сокет адрес:порт','Сетевой стек'], quiz:['Может ли один серверный порт обслуживать много клиентов?','Да, соединения различаются конечными точками','Нет, всегда только один','Только через DNS',0], tags:['socket','python','ss','client-server'], notes:['bind закрепляет локальную точку, listen переводит сервер в режим ожидания, accept возвращает отдельное соединение с клиентом.','Проверяй адрес привязки: 127.0.0.1 ограничивает доступ локальной машиной, а 0.0.0.0 слушает все IPv4-интерфейсы.','Открытый сокет ещё не говорит о доступности извне: трафик могут остановить firewall, маршрутизация или политика облака.'] }),

  B({ id:'crypto-model', path:'crypto', title:'Что защищает криптография', brief:'Разделяй шифрование, целостность, аутентификацию и хэширование.', concept:'Шифрование скрывает содержимое от того, у кого нет ключа. Контроль целостности помогает заметить изменение, а цифровая подпись связывает сообщение с обладателем ключа. Хэш-функция вычисляет отпечаток данных, но сама по себе не скрывает их. Без модели угроз легко выбрать правильный алгоритм для неправильной задачи.', command:'sha256sum lab.txt', meaning:'Вычислить отпечаток своего файла для сравнения копий.', output:'<64 шестнадцатеричных символа>  lab.txt', flow:['Данные','Криптографическая операция','Свойство защиты'], quiz:['Скрывает ли SHA-256 содержимое файла?','Нет, это хэш','Да, это шифрование','Только в TLS',0], tags:['crypto','hash','шифрование','целостность'], notes:['Симметричное шифрование использует общий секрет; асимметричное — пару открытого и закрытого ключей. Они решают разные части общей задачи.','Перед выбором инструмента сформулируй: от кого защищаем данные, кто должен уметь читать и как проверить неизменность.','Криптография не исправит слабый пароль, скомпрометированный конечный узел или доверие к неподлинному открытому ключу.'], visual:{title:'Разные свойства защиты',kind:'compare',items:[{label:'Шифрование',detail:'Скрывает содержание при наличии секретного ключа'},{label:'Хэш',detail:'Даёт отпечаток, но не скрывает данные'},{label:'Подпись',detail:'Помогает проверить происхождение и целостность'}]} }),
  B({ id:'symmetric-aead', path:'crypto', title:'Симметричное шифрование и AEAD', brief:'Почему режим и nonce столь же важны, как имя алгоритма.', concept:'Блочный шифр сам по себе преобразует блок фиксированной длины. Режим работы превращает его в схему для сообщений. Современные схемы AEAD одновременно дают конфиденциальность и проверку целостности; повтор nonce с тем же ключом в некоторых режимах опасен. Самодельные схемы в реальной системе не нужны.', command:'openssl list -cipher-algorithms | head', meaning:'Посмотреть поддерживаемые алгоритмы в установленном OpenSSL.', output:'AES-128-GCM ...', flow:['Ключ + nonce','AEAD-шифрование','Шифртекст + тег'], quiz:['Что проверяет тег AEAD?','Целостность и подлинность шифртекста','Размер диска','Скорость DNS',0], tags:['aes','aead','nonce','шифрование'], notes:['Nonce — уникальное для операции значение; его можно передавать открыто, но правила уникальности определяются выбранной схемой.','При расшифровании сначала проверяют тег. Если проверка не прошла, результат нельзя считать достоверным текстом.','Нельзя сравнивать «AES против TLS»: AES — примитив, TLS — протокол, использующий несколько примитивов и правила обмена ключами.'] }),
  B({ id:'public-key', path:'crypto', title:'Открытый ключ и подпись', brief:'Как пара ключей помогает обмену и проверке личности.', concept:'Открытый ключ можно распространять, закрытый должен оставаться секретным. Подпись создаётся закрытым ключом и проверяется открытым. Для шифрования и обмена секретами применяются подходящие схемы и обёртки, а не «сырой RSA». Доверие к ключу требует отдельной проверки его принадлежности.', command:'openssl pkey -in lab-private.pem -pubout -out lab-public.pem', meaning:'Извлечь открытый ключ из собственной учебной пары; приватный файл не публиковать.', output:'lab-public.pem', flow:['Закрытый ключ','Подпись','Проверка открытым ключом'], quiz:['Какой ключ должен оставаться секретным?','Закрытый','Открытый','Оба всегда публикуют',0], tags:['rsa','ключ','подпись','pki'], notes:['Математическая стойкость не решает вопрос «чей это ключ». Сертификаты и доверенные каналы связывают ключ с идентичностью.','В собственной лаборатории сравни отпечатки открытых ключей до использования и после экспорта.','Утечка закрытого ключа требует отзыва/замены: дальнейшая подпись или доступ могут быть подделаны.'] }),
  B({ id:'tls-trust', path:'crypto', title:'TLS: цепочка доверия', brief:'Сертификат, доменное имя, центр сертификации и шифрованный канал.', concept:'TLS защищает соединение после согласования версий, проверки сертификата и выработки ключей сессии. Клиент должен проверить подпись цепочки, срок действия и совпадение имени сервера. Шифрование без проверки подлинности оставляет возможность разговора с подставным сервером.', command:'openssl s_client -connect example.org:443 -servername example.org </dev/null', meaning:'Посмотреть сертификат публичного учебного домена; для Windows используйте WSL/Kali.', output:'Verify return code: 0 (ok)', flow:['ClientHello','Сертификат + ключи','Защищённые данные'], quiz:['Что проверяет клиент в сертификате сервера?','Цепочку доверия и имя','Только цвет сайта','Права chmod',0], tags:['tls','сертификат','ca','https'], notes:['Центр сертификации удостоверяет связь имени и ключа. Браузер доверяет набору корневых сертификатов, а сервер обычно присылает промежуточные.','При ошибке TLS проверь имя, время на машине, срок сертификата и полноту цепочки. Не выключай проверку как постоянное «решение».','TLS защищает канал до сервера, но не гарантирует, что само приложение безопасно или что сервер хранит данные правильно.'], visual:{title:'Проверка доверия',kind:'sequence',items:[{label:'Клиент',detail:'Запрашивает соединение для имени'},{label:'Сервер',detail:'Предъявляет сертификат и ключевые параметры'},{label:'Клиент',detail:'Проверяет имя, цепочку и срок; создаёт ключ сессии'}]} }),
  B({ id:'key-exchange', path:'crypto', title:'Обмен ключами и прямая секретность', brief:'Пойми идею Диффи — Хеллмана без зубрёжки формул.', concept:'Стороны могут получить общий секрет, передавая по открытому каналу только публичные значения. В эфемерном обмене одноразовые ключи помогают сохранить прошлые сессии даже при будущей утечке долгосрочного ключа. Сам по себе обмен ключами не аутентифицирует участника, поэтому TLS связывает его с проверенным сертификатом.', command:'openssl ciphers -v | head', meaning:'Посмотреть примеры наборов шифрования, которые поддерживает локальная установка.', output:'TLS_AES_256_GCM_SHA384 ...', flow:['Публичные параметры','Обмен значениями','Общий секрет'], quiz:['Что добавляет проверка сертификата к обмену ключами?','Подлинность стороны','Размер пакета','Права файла',0], tags:['diffie-hellman','ecdh','forward secrecy','tls'], notes:['Каждая сторона использует свой закрытый параметр и публичное значение партнёра; общий результат совпадает без передачи закрытых параметров.','В современных протоколах важны не только формулы, но и проверка параметров, случайность, привязка к контексту и защита от повтора.','Если проигнорировать аутентификацию, посредник может провести отдельный обмен с каждой стороной.'], visual:{title:'Общий секрет без передачи секрета',kind:'sequence',items:[{label:'Клиент',detail:'Создаёт закрытый a и публичное A'},{label:'Канал',detail:'Передаются A и B, не a и b'},{label:'Сервер',detail:'Обе стороны вычисляют одинаковый секрет'}]} }),

  B({ id:'osint-method', path:'recon', title:'OSINT: открытые источники', brief:'Собирай проверяемые сведения с учётом актуальности и права доступа.', concept:'OSINT — работа с открытыми источниками: официальными страницами, техническими метаданными, реестрами, архивами и публикациями. Ценность не в объёме ссылок, а в проверке происхождения, времени и связи с согласованной целью. Публичность данных не означает разрешение на вредные действия.', command:'dig example.org MX +short', meaning:'Пример пассивного запроса почтовых записей для учебного домена.', output:'0 .', flow:['Открытый источник','Проверка времени и происхождения','Гипотеза'], quiz:['Что делает вывод OSINT надёжнее?','Независимая проверка источника и даты','Количество скриншотов','Скрытие происхождения',0], tags:['osint','shodan','maltego','источники'], notes:['Отделяй первичный источник от перепечатки и машинной агрегации. Фиксируй URL, дату наблюдения и ограничения.','Строй карту активов: домены, организации, внешние сервисы и владельцы. Связь между объектами должна иметь доказательство.','Старый результат поисковой системы не доказывает текущее состояние сервиса. Повторная проверка может требовать отдельного разрешения.'] }),
  B({ id:'mail-metadata', path:'recon', title:'DNS и почтовые метаданные', brief:'MX, SPF, DKIM и DMARC как карта почтовой инфраструктуры.', concept:'MX указывает почтовые серверы домена. SPF описывает разрешённые источники отправки, DKIM позволяет проверить подпись письма, DMARC задаёт политику обработки и отчётности. Эти механизмы снижают риск подделки домена, но не делают любое письмо от похожего имени безопасным.', command:'dig example.org TXT +short', meaning:'Посмотреть публичные TXT-записи учебного домена.', output:'"v=spf1 ..."', flow:['DNS-записи','Политика почты','Проверка сообщения'], quiz:['За что отвечает MX?','Куда доставлять почту домена','За хэш пароля','За TCP-флаг SYN',0], tags:['dns','mx','spf','dkim','dmarc','smtp'], notes:['Почтовый клиент и сервер могут применять несколько проверок; результат зависит от выравнивания доменов и политики организации.','Изучай реальные заголовки своих тестовых писем и отмечай Authentication-Results. Сравни видимый From с техническими полями.','Успешные SPF/DKIM не доказывают, что содержание письма безопасно: злоумышленник может контролировать собственный домен.'] }),
  B({ id:'scan-strategy', path:'recon', title:'Стратегия сканирования', brief:'Выбирай цель, скорость, проверку и способ фиксации результата.', concept:'Активное сканирование создаёт трафик и может влиять на сервис. Начинайте с малой согласованной области и понятной цели: доступность, порт или версия. Сохраняйте время, команду, точку наблюдения и исходный вывод; после сканера подтверждайте важные факты другим способом.', command:'nmap -sT -sV --version-light 192.0.2.10', meaning:'Осторожная проверка одной учебной машины в собственном стенде.', output:'22/tcp open ssh OpenSSH ...', flow:['Scope + лимиты','Сканирование','Подтверждение'], quiz:['Что делать с найденной версией службы?','Проверить точность и контекст','Считать уязвимость доказанной','Сразу изменить сервис',0], tags:['nmap','masscan','scan','scope'], notes:['SYN-, connect- и UDP-проверки дают разные сигналы и требуют разной интерпретации. Сила вывода зависит от ответа сети.','Скорость и параллельность выбираются под надёжность цели, особенно в производственной сети. Ограничения согласуются заранее.','Баннер может быть ложным или изменённым. Закрытый порт из одного сегмента может быть открыт из другого.'], caution:'Сканируйте только свои машины или явно согласованные адреса.' }),
  B({ id:'vuln-intelligence', path:'recon', title:'Базы уязвимостей и применимость', brief:'От CVE к условиям эксплуатации и реальному риску.', concept:'CVE — идентификатор описанной уязвимости, а не оценка состояния конкретного хоста. Для вывода нужны точная версия, сборка, конфигурация, доступность уязвимого пути и смягчающие меры. Приоритет исправления зависит от последствий в вашей среде и доступности эксплуатации.', command:'apt list --installed | grep openssl', meaning:'Узнать установленную версию пакета в собственной Kali/Debian-системе.', output:'openssl/... 3.x amd64 [installed]', flow:['Версия и конфигурация','Условия уязвимости','Приоритет исправления'], quiz:['Достаточно ли совпадения номера версии для подтверждения?','Нет, нужна проверка сборки и условий','Да, всегда','Только если есть скриншот',0], tags:['cve','nvd','vulnerability','риск'], notes:['Дистрибутив может переносить исправление в старый номер версии, поэтому учитывай бюллетень поставщика и номер сборки.','Сохраняй источник сведений, дату проверки, затронутый компонент и безопасное доказательство.','Высокий балл CVSS не заменяет оценки доступности и влияния на конкретный актив.'] }),
  B({ id:'nat-ipv6', path:'recon', title:'NAT и IPv6 меняют картину', brief:'Почему внешний адрес не равен одному хосту и почему нельзя забывать IPv6.', concept:'NAT переводит адреса/порты между сетями, поэтому один внешний адрес может обслуживать много внутренних машин. IPv6 даёт отдельное адресное пространство и правила маршрутизации. Инвентаризация только IPv4 или только одной точки наблюдения оставляет пробелы.', command:'ip -br address; ip -6 route', meaning:'Посмотреть адреса и маршруты IPv6 на своей Linux-машине.', output:'eth0 UP 192.0.2.10/24 2001:db8::10/64', flow:['Внешнее наблюдение','NAT / IPv6','Реальная топология'], quiz:['Гарантирует ли один публичный IPv4 один внутренний хост?','Нет','Да','Только при HTTPS',0], tags:['nat','ipv6','маршрут','инвентаризация'], notes:['Портовое сопоставление NAT зависит от текущих правил и соединений; оно не раскрывает всю внутреннюю архитектуру.','Проверяй адреса интерфейсов, AAAA-записи и политики firewall для IPv6, если он включён в scope.','Невозможность увидеть сервис извне не доказывает, что сервис отсутствует внутри сети.'] }),
  B({ id:'social-trust', path:'recon', title:'Социальная инженерия и дипфейки', brief:'Изучай цепочку доверия и способы проверки запроса.', concept:'Социальная инженерия воздействует на решение человека: срочность, авторитет, страх, помощь или привычка. Поддельный голос и видео снижают надёжность узнавания собеседника. Технические метаданные письма и независимый обратный звонок помогают проверять запрос, особенно если он связан с доступом или деньгами.', command:'printf "Проверка: кто просит, что просит, как подтвердить отдельно?\n"', meaning:'Короткая памятка для учебного разбора подозрительного запроса.', output:'Проверка: кто просит, что просит, как подтвердить отдельно?', flow:['Необычный запрос','Проверка по независимому каналу','Решение'], quiz:['Что лучше при неожиданной просьбе перевести деньги?','Проверить по ранее известному каналу','Довериться голосу','Ответить на письмо с паролем',0], tags:['phishing','deepfake','социальная инженерия'], notes:['Тренируй распознавание контекста: неожиданный канал, давление временем и попытка обойти обычную процедуру согласования.','Для учебных кампаний по осведомлённости согласуй участников, объём собираемых данных и способ обратной связи.','Отсутствие явной орфографической ошибки не означает подлинность: современные подделки могут выглядеть аккуратно.'] }),
  B({ id:'recon-evidence', path:'recon', title:'Доказательства и неопределённость', brief:'Делай выводы, которые можно проверить повторно.', concept:'Одна и та же сеть выглядит по-разному из разных сегментов и в разное время. Хорошая заметка фиксирует наблюдение, инструмент, параметры, точку наблюдения и ограничение вывода. Гипотезы нужно явно обозначать, чтобы читатель не принял предположение за установленный факт.', command:'date -Iseconds; ip -br a; ss -lnt', meaning:'Записать время, контекст сетевого узла и локальные слушающие порты.', output:'2026-...\neth0 UP ...\nLISTEN ...', flow:['Наблюдение','Контекст и источник','Вывод с оговоркой'], quiz:['Что превращает скриншот в полезное доказательство?','Контекст, время и воспроизводимость','Большой размер файла','Тёмная тема терминала',0], tags:['evidence','scope','отчёт','методология'], notes:['Сохраняй исходные данные отдельно от интерпретации. Для изменений в системе фиксируй шаги и возможность отката.','Используй короткий чек-лист: кто, где, когда, чем, что получилось и что не проверено.','Даже правильная команда может дать неполный вывод из-за прав, фильтрации, кэша и ограниченного времени наблюдения.'] }),

  B({ id:'http-session', path:'web', title:'HTTP, cookie и сессия', brief:'Пойми, как браузер сохраняет состояние поверх HTTP.', concept:'HTTP сам по себе не хранит состояние между запросами. Сервер связывает запросы через cookie или иной токен сессии. Атрибуты Secure, HttpOnly и SameSite уменьшают разные классы рисков, но работают вместе с серверной проверкой срока действия и прав доступа.', command:'curl -I https://example.org', meaning:'Посмотреть заголовки ответа безопасного учебного домена.', output:'HTTP/2 200\ncontent-type: text/html', flow:['Запрос','Cookie / токен','Контекст сессии'], quiz:['Что связывает отдельные HTTP-запросы в одну сессию?','Сессионный идентификатор','MAC-адрес браузера','Только DNS',0], tags:['http','cookie','session','sameSite'], notes:['Cookie — способ переноса значения; сама авторизация определяется сервером. Клиенту нельзя доверять роль только потому, что она записана в запросе.','При анализе собственного приложения проверь срок жизни токена, выход из системы, смену токена после входа и ограничения доступа к другим объектам.','HttpOnly снижает риск чтения cookie из JavaScript, но не устраняет XSS и не заменяет проверку действий на сервере.'], visual:{title:'Состояние поверх отдельных запросов',kind:'sequence',items:[{label:'Вход',detail:'Сервер создаёт сессию'},{label:'Браузер',detail:'Передаёт cookie в следующем запросе'},{label:'Сервер',detail:'Проверяет сессию и полномочия'}]} }),
  B({ id:'web-proxy', path:'web', title:'Прокси для изучения запросов', brief:'Burp Suite и ZAP как лабораторный микроскоп HTTP.', concept:'Прокси между браузером и учебным приложением показывает запрос, ответ, параметры, заголовки и cookie. Это помогает увидеть, какие данные уходят на сервер и где принимается решение. Перехват HTTPS в собственном стенде требует настройки доверенного лабораторного сертификата; с реальными секретами работайте осторожно.', command:'curl -v https://example.org -o /dev/null', meaning:'Посмотреть метаданные запроса и ответа без сохранения тела страницы.', output:'> GET / HTTP/2\n< HTTP/2 200', flow:['Браузер','Прокси-анализатор','Учебный сервер'], quiz:['Для чего нужен прокси при изучении веб-приложения?','Видеть и разбирать HTTP-обмен','Менять права Linux','Настраивать IP-маршрут',0], tags:['burp','zaproxy','http','proxy'], notes:['Повторитель запросов позволяет сравнивать ответы на контролируемые изменения одного параметра. Важно сохранять исходный запрос для сравнения.','Ищи доверенные и недоверенные данные: URL, тело, заголовки, cookie и ответы сторонних сервисов.','Наблюдение запроса не доказывает уязвимость: нужен контрольный эксперимент и понимание серверного поведения.'] }),
  B({ id:'sql-injection-concept', path:'web', title:'SQL-инъекция: граница данных и кода', brief:'Почему параметризованный запрос защищает лучше ручной очистки строки.', concept:'Инъекция возникает, когда внешние данные становятся частью синтаксиса запроса. Параметризованный запрос передаёт текст пользователя отдельно от структуры SQL, поэтому база интерпретирует его как значение. Проверка только на клиенте недостаточна: запрос можно создать без браузера.', command:'python3 -c "import sqlite3; print(sqlite3.connect(\":memory:\").execute(\"SELECT ?\", (\"hello\",)).fetchone())"', meaning:'Показать принцип параметра на локальной базе в памяти; никакой внешней цели нет.', output:"('hello',)", flow:['Недоверенное значение','Параметр SQL','Запрос без смены структуры'], quiz:['Что отделяет ввод пользователя от SQL-синтаксиса?','Параметризованный запрос','Скрытая кнопка','Смена DNS',0], tags:['sqli','sqlmap','prepared statement','инъекция'], notes:['Причина ошибки — смешение кода и данных. Экранирование вручную легко ошибается при разных кодировках и контекстах.','В своём приложении проверь все места формирования запросов, включая сортировку и имена полей, которые не всегда параметризуются как значения.','Отсутствие ошибки SQL в ответе не доказывает отсутствие инъекции: приложение может скрывать сообщения и всё равно выполнять опасный запрос.'], visual:{title:'Безопасная граница',kind:'compare',items:[{label:'Конкатенация',detail:'Ввод попадает в синтаксис SQL'},{label:'Параметры',detail:'Шаблон SQL отдельно, значение отдельно'},{label:'Проверка',detail:'Права учётной записи БД минимальны'}]} }),
  B({ id:'xss-concept', path:'web', title:'XSS: когда данные становятся кодом', brief:'Отражённый и хранимый XSS, контекст вывода и защита.', concept:'XSS появляется, когда недоверенный текст браузер воспринимает как код в контексте страницы. Отражённый вариант возвращает ввод в том же ответе, хранимый сохраняет его и показывает другим пользователям. Ключевая защита — контекстное кодирование вывода и безопасные DOM API; CSP служит дополнительным барьером.', command:'printf "%s\n" "<tag>текст</tag>"', meaning:'Безопасная иллюстрация различия между текстом и разметкой; браузер не запускается.', output:'<tag>текст</tag>', flow:['Недоверенный ввод','Контекст HTML/DOM','Интерпретация браузером'], quiz:['Где исправлять основную причину XSS?','На границе вывода в нужном контексте','Только в DNS','Через chmod 777',0], tags:['xss','owasp zap','csp','html'], notes:['HTML-текст, HTML-атрибут, URL и JavaScript-строка требуют разных правил кодирования. Универсальной замены одного символа недостаточно.','Исследуй собственное приложение через безопасные контрольные строки и следи, попадают ли они как текст или разметка.','CSP уменьшает последствия некоторых ошибок, но слабая политика или опасные DOM-операции оставят путь атаки.'], visual:{title:'Две формы одной причины',kind:'compare',items:[{label:'Отражённый XSS',detail:'Ввод возвращается сразу в ответе'},{label:'Хранимый XSS',detail:'Ввод сохраняется и попадает в будущие ответы'},{label:'Защита',detail:'Контекстное кодирование + безопасный DOM'}]} }),
  B({ id:'password-storage', path:'web', title:'Пароли, соль и медленный хэш', brief:'Почему SHA-256 недостаточен как схема хранения паролей.', concept:'Пароль нельзя хранить в открытом виде. Для хранения нужен специализированный медленный алгоритм с индивидуальной солью, например Argon2id или подходящая альтернатива. Соль мешает использовать одинаковые предварительно посчитанные таблицы; высокая стоимость вычисления повышает цену перебора.', command:'python3 -c "import secrets; print(secrets.token_hex(16))"', meaning:'Сгенерировать случайную соль в своей лаборатории.', output:'32 шестнадцатеричных символа', flow:['Пароль + соль','Медленная функция','Хранимый результат'], quiz:['Зачем индивидуальная соль?','Чтобы одинаковые пароли давали разные результаты','Чтобы пароль можно было расшифровать','Чтобы убрать необходимость MFA',0], tags:['password','salt','argon2','hashcat'], notes:['Хэш пароля не должен быть обратимым. При проверке введённый пароль проходит ту же функцию с сохранённой солью и параметрами.','Параметры стоимости нужно выбирать под оборудование и периодически пересматривать; миграция возможна при следующем успешном входе.','Даже хорошее хранение не защищает от фишинга и повторного использования паролей. Нужны MFA, ограничения попыток и оповещения.'] }),
  B({ id:'access-control-web', path:'web', title:'Авторизация на каждом объекте', brief:'Почему вход в систему не равен праву читать любую запись.', concept:'Аутентификация отвечает на вопрос «кто пользователь», авторизация — «можно ли ему это действие над этим объектом». Проверка должна происходить на сервере для каждого запроса и объекта. Скрытая кнопка в интерфейсе не является контролем доступа.', command:'curl -I https://example.org', meaning:'Иллюстрация HTTP-запроса; проверку авторизации выполняют только на собственном приложении.', output:'HTTP/2 200', flow:['Пользователь','Политика доступа','Конкретный объект'], quiz:['Где должна решаться авторизация?','На сервере для каждого объекта','Только в CSS','По имени файла клиента',0], tags:['authorization','idor','session','web'], notes:['Объект может принадлежать пользователю, группе или организации. Политика должна учитывать и действие, и контекст.','Тестируй разные учебные учётные записи и сравни доступ к собственным и чужим объектам в согласованном стенде.','Ответ 403 полезен, но также важно не раскрывать чувствительные сведения в ошибках, списках и метаданных.'] }),

  B({ id:'fuzzing-model', path:'host', title:'Фаззинг: исследуй границы ввода', brief:'Как систематически находят необычное поведение программы.', concept:'Фаззер создаёт множество изменённых входных данных и наблюдает за сбоями, зависаниями и новыми путями выполнения. Цель — обнаружить дефект в собственной программе или разрешённой цели; найденный crash ещё не доказывает эксплуатируемость. Хороший стенд изолирован и позволяет воспроизвести вход.', command:'python3 -c "print(\"A\" * 64)"', meaning:'Безопасный пример генерации тестового ввода для собственной программы.', output:'AAAAAAAA... (64 символа)', flow:['Корпус входов','Мутация + запуск','Сбой и воспроизведение'], quiz:['Что означает найденный crash?','Есть повод исследовать дефект','Уязвимость доказана автоматически','Программа безопасна',0], tags:['fuzzing','afl++','coverage','crash'], notes:['Покрытие помогает выбирать входы, которые открывают новые участки кода. Начальный корпус должен содержать корректные небольшие примеры формата.','Сохраняй конкретный вход, версию программы, параметры запуска и стек сбоя. Минимизируй вход, чтобы понять причину.','Сбой может быть обычным отказом без нарушения границ безопасности; отсутствие сбоев не доказывает отсутствие ошибок.'], visual:{title:'Цикл фаззера',kind:'sequence',items:[{label:'Вход',detail:'Корректный образец или мутация'},{label:'Программа',detail:'Запуск в изоляции + наблюдение покрытия'},{label:'Анализ',detail:'Сбой → повтор → минимизация → исправление'}]} }),
  B({ id:'crash-triage', path:'host', title:'От сбоя к причине', brief:'Воспроизводимость, минимизация и ответственное сообщение.', concept:'Когда программа упала, сначала воспроизведите сбой в контролируемой среде. Затем уменьшите вход до минимального, сравните со стабильной версией и определите, какая проверка отсутствует. Лишь после анализа влияния можно оценивать безопасность дефекта.', command:'ulimit -c', meaning:'Проверить настройку создания core-файлов в собственной Linux-сессии.', output:'0', flow:['Сбой','Минимальный вход','Корневая причина'], quiz:['Что полезно сохранить вместе со сбоем?','Вход, версия и условия запуска','Только цвет окна','Чужие учётные данные',0], tags:['debugging','core dump','fuzzing','triage'], notes:['Разные классы ошибок дают похожий симптом «программа завершилась». Используй стек, журналы и средства диагностики памяти.','Тест на исправление должен воспроизводить исходный дефект и проходить после правки.','Core dump может содержать секреты процесса; доступ к файлам дампа нужно ограничивать.'] }),
  B({ id:'symbolic-execution', path:'host', title:'Символьное выполнение', brief:'Как инструмент исследует ветви программы через ограничения.', concept:'Символьный исполнитель рассматривает некоторые входы как переменные и строит ограничения для ветвей. Решатель подбирает значение, которое приведёт к интересующему пути. Метод полезен для небольших функций и исследовательских задач, но сталкивается со взрывом числа путей, внешним состоянием и сложными библиотеками.', command:'python3 -c "print((3 < 5) and (3 != 0))"', meaning:'Миниатюрная иллюстрация условий, которые решатель мог бы рассматривать как ограничения.', output:'True', flow:['Символьный вход','Условия ветвей','Решение ограничений'], quiz:['Что ограничивает символьное выполнение?','Взрыв числа путей','Только размер монитора','DNS-кэш',0], tags:['symbolic execution','angr','dse','constraints'], notes:['Обычное выполнение проверяет конкретный ввод, символьное — множество возможных значений, пока модель остаётся управляемой.','Формулируй узкую цель: достигнуть строки кода или избежать ошибочной ветви. Затем проверяй найденный вход обычным запуском.','Модель может упрощать поведение ОС или библиотек; результат без реальной проверки остаётся гипотезой.'] }),
  B({ id:'kernel-boundary', path:'host', title:'Пользовательское пространство и ядро', brief:'Системные вызовы, модули и цена ошибки с высокими правами.', concept:'Процесс пользователя обращается к ядру через системные вызовы, например открыть файл или создать сокет. Ядро управляет памятью, устройствами и доступом. Код модуля ядра обладает широкими возможностями и может нарушить работу всей машины; анализ такой темы проводите на снимке изолированной ВМ.', command:'uname -r; lsmod | head', meaning:'Узнать версию ядра и часть загруженных модулей без изменения системы.', output:'6.x...\nModule Size Used by', flow:['Процесс','Системный вызов','Ядро / ресурс'], quiz:['Почему модуль ядра требует особой осторожности?','Работает с высокими привилегиями','Всегда безвреден','Не видит память',0], tags:['kernel','syscall','module','rootkit'], notes:['Граница пользователь/ядро ограничивает прямой доступ приложения к устройствам и памяти других процессов.','Для диагностики изучай версию ядра, загруженные модули, журналы и подписывание модулей там, где оно применяется.','Сам по себе неизвестный модуль не доказывает вредоносность; нужно установить происхождение, назначение и поведение.'] }),
  B({ id:'persistence-detection', path:'host', title:'Устойчивость вредоносного ПО: где искать', brief:'Службы, автозапуск, задачи и необычные сетевые связи.', concept:'Закрепление в системе может использовать службы, планировщики, пользовательский автозапуск или изменённые компоненты. Анализ строится на сравнении ожидаемого состояния с фактическим: происхождение файла, время изменения, подпись/хэш и связанные процессы. Не удаляйте подозрительный объект до фиксации доказательств и плана восстановления.', command:'systemctl list-unit-files --type=service | head; crontab -l', meaning:'Показать часть точек автозапуска на собственной Linux-машине.', output:'UNIT FILE STATE PRESET\n...', flow:['Точка автозапуска','Процесс / соединение','Проверка происхождения'], quiz:['Что сделать до удаления подозрительного файла?','Зафиксировать доказательства и план восстановления','Очистить все журналы','Выдать chmod 777',0], tags:['persistence','rootkit','malware','systemd'], notes:['Необычное имя процесса — слабый сигнал. Сравни путь бинарника, владельца, пакет, время появления и сетевое поведение.','На снимке ВМ удобно сравнивать состояние до и после учебного упражнения, чтобы понять механизм изменения.','Умелое скрытие может искажать вывод локальных инструментов; при серьёзном инциденте нужны независимые источники телеметрии.'] }),
  B({ id:'privilege-boundary', path:'host', title:'Повышение привилегий как класс риска', brief:'Где пересекается граница прав и как её укреплять.', concept:'Повышение привилегий — переход от ограниченной роли к более широкой через ошибку конфигурации, уязвимость или лишние полномочия. Аудит ищет опасные разрешения, устаревшие компоненты и ненужные пути к root. Проверка проводится по согласованному сценарию и заканчивается исправлением границы.', command:'sudo -l; find /usr/local/bin -perm /4000 -type f 2>/dev/null', meaning:'Инвентаризация разрешённых команд sudo и SUID-файлов в собственной лаборатории.', output:'Matching Defaults entries ...\n/path/to/binary', flow:['Начальная роль','Ошибочная граница','Расширенные права'], quiz:['Что снижает риск эскалации?','Минимальные права и обновления','Общий пароль root','Открытая запись всем',0], tags:['privilege escalation','suid','sudo','hardening'], notes:['SUID запускает файл с эффективным UID владельца; это мощный механизм, поэтому список таких файлов должен быть объяснимым.','Проверь, какие команды разрешены через sudo и не дают ли они косвенно изменять критичные файлы или запускать произвольный код.','Наличие SUID само по себе нормально для ряда системных утилит. Риск зависит от программы, версии и доступных пользователю операций.'] }),

  B({ id:'segmentation', path:'enterprise', title:'Сегментация и маршруты доверия', brief:'Почему доступ к одному узлу не означает доступ ко всей сети.', concept:'Сегментация делит среду на зоны и ограничивает допустимые потоки между ними. Двухинтерфейсный узел видит два сегмента, но это не делает весь трафик автоматически разрешённым. Для оценки рисков строят карту маршрутов и правил доступа, затем проверяют только согласованные связи.', command:'ip route; ip -br address', meaning:'Показать интерфейсы и маршруты собственного лабораторного узла.', output:'eth0 192.0.2.10/24\neth1 198.51.100.10/24', flow:['Сегмент A','Маршрутизатор / политика','Сегмент B'], quiz:['Что ограничивает поток между зонами?','Маршруты и правила доступа','Только имя хоста','Цвет сетевого кабеля',0], tags:['segmentation','pivoting','routing','firewall'], notes:['Сегмент может быть VLAN, подсетью, облачной группой безопасности или их сочетанием. Название зоны не заменяет проверки правил.','Составь матрицу «источник → назначение → порт → цель связи». Она помогает понять, какие потоки необходимы бизнесу.','Видимость маршрута не равна разрешению приложения: firewall, ACL и аутентификация действуют независимо.'], visual:{title:'Путь через зоны',kind:'sequence',items:[{label:'Рабочая станция',detail:'Ограниченный исходный сегмент'},{label:'Политика',detail:'Разрешены только нужные направления и порты'},{label:'Сервис',detail:'Отдельная проверка личности и полномочий'}]} }),
  B({ id:'directory-services', path:'enterprise', title:'Каталог: LDAP и Active Directory', brief:'Пользователи, группы, компьютеры и отношения между ними.', concept:'Каталог хранит объекты организации и их атрибуты. LDAP — протокол запросов к каталогу, Active Directory — более широкая служба идентичности и управления Windows-средой. Участие в группе и наследование прав создают сложный граф доступа, который важно документировать и минимизировать.', command:'getent passwd | head', meaning:'Локальная аналогия запроса к базе учётных записей Linux.', output:'root:x:0:0:root:/root:/bin/bash', flow:['Объект','Группа и атрибуты','Решение о доступе'], quiz:['Что описывает LDAP?','Протокол обращения к каталогу','Алгоритм шифрования диска','TCP-флаг',0], tags:['ldap','active directory','groups','identity'], notes:['У одного пользователя может быть несколько групп, а группа — входить в другую. Это усложняет анализ эффективных полномочий.','В лаборатории рисуй граф «пользователь → группа → ресурс» и проверяй, где возникают лишние пути к привилегиям.','Не всякий атрибут каталога актуален: уволенные сотрудники, старые компьютеры и наследованные правила требуют ревизии.'] }),
  B({ id:'kerberos-model', path:'enterprise', title:'Kerberos: билеты и служба', brief:'Пойми обмен билетами до изучения атак на идентичность.', concept:'Kerberos использует доверенный центр и билеты, чтобы клиент доказал право обратиться к службе без повторной передачи пароля самой службе. Сначала клиент получает билет для обращения к центру выдачи, затем билет для конкретного сервиса. Время, имена сервисов и защита ключей критичны для корректной работы.', command:'date -Iseconds', meaning:'Проверить системное время: рассинхронизация часто мешает билетной аутентификации.', output:'2026-10-27T...', flow:['Клиент','Центр выдачи билетов','Сервис'], quiz:['Зачем клиенту сервисный билет?','Доказать право обратиться к конкретной службе','Назначить IP-адрес','Обновить ядро',0], tags:['kerberos','ticket','kdc','active directory'], notes:['TGT позволяет запрашивать сервисные билеты в пределах срока действия. Сервисный билет предназначен определённой службе.','Для диагностики в своём домене проверяй время, DNS, имя службы и журналы входа.','Наличие билета не делает действия пользователя безграничными: служба должна отдельно проверить полномочия.'], visual:{title:'Билетная схема',kind:'sequence',items:[{label:'Клиент',detail:'Получает TGT после входа'},{label:'KDC',detail:'Выдаёт билет для нужной службы'},{label:'Сервис',detail:'Проверяет билет и затем полномочия'}]} }),
  B({ id:'ntlm-model', path:'enterprise', title:'NTLM и границы старой аутентификации', brief:'Разбери challenge-response и зачем сокращать область его применения.', concept:'NTLM — семейство механизмов аутентификации Windows, использующее ответ на вызов на основе секрета. Старые схемы и широкое применение NTLM увеличивают риск повторного использования учётных данных и ошибок конфигурации. В современной среде важно знать, где NTLM ещё нужен и где возможно перейти на более сильные механизмы.', command:'whoami /user', meaning:'Команда Windows для просмотра собственной учётной записи и SID.', output:'USER INFORMATION ... SID', flow:['Вызов сервера','Ответ клиента','Проверка учётной записи'], quiz:['Почему важно инвентаризировать NTLM?','Чтобы сократить устаревшие пути аутентификации','Чтобы настроить chmod','Чтобы заменить DNS',0], tags:['ntlm','windows','authentication','sid'], notes:['Хэш пароля и сетевой ответ — разные объекты; оба требуют защиты и корректной политики доступа.','Проверяй, какие приложения ещё зависят от NTLM, и планируй изменения совместно с владельцами сервисов.','Отключение механизма без инвентаризации может сломать легитимные сервисы, поэтому переход делается поэтапно.'] }),
  B({ id:'ad-dns', path:'enterprise', title:'DNS как основа корпоративного входа', brief:'Почему ошибки DNS ломают поиск контроллера домена.', concept:'В доменной сети клиенты используют DNS, в том числе SRV-записи, чтобы находить службы каталога и контроллеры домена. Неверная зона, кэш или запись может приводить к проблемам входа, даже если IP-связность есть. Диагностика должна сопоставлять ответ DNS с ожидаемой топологией.', command:'nslookup -type=SRV _ldap._tcp.example.test', meaning:'Учебный пример запроса SRV-записи внутри собственной лабораторной доменной зоны.', output:'service = 0 100 389 dc1.example.test', flow:['Клиент','DNS SRV','Контроллер домена'], quiz:['Для чего SRV-запись?','Найти сервис по имени и порту','Хранить пароль','Менять MAC-адрес',0], tags:['dns','srv','ldap','active directory'], notes:['В обычном DNS A/AAAA дают адрес узла, а SRV указывает на службу и её параметры.','При сбое сравни DNS-сервер клиента, ответ на SRV, адрес найденного узла и доступность нужного порта.','Правильный DNS-ответ не гарантирует успешный вход: далее действуют сеть, время, аутентификация и полномочия.'] }),
  B({ id:'enterprise-graph', path:'enterprise', title:'Граф доступа и приоритет защиты', brief:'Как читать цепочки полномочий и устранять лишние связи.', concept:'Корпоративные права образуют граф: пользователь состоит в группе, группа имеет доступ к машине или ресурсу, служба доверяет другой службе. Инструменты визуализации помогают увидеть короткие пути к критичным активам. Каждый путь нужно перепроверить и обсудить с владельцами, прежде чем менять доступ.', command:'printf "user → group → host → service\n"', meaning:'Простая схема связи для собственного учебного графа.', output:'user → group → host → service', flow:['Учётная запись','Связи полномочий','Критичный ресурс'], quiz:['Что делать с найденным путём в графе доступа?','Подтвердить связи и снизить лишние права','Считать все узлы скомпрометированными','Удалить весь каталог',0], tags:['bloodhound','graph','ad','least privilege'], notes:['Граф отражает собранные данные и время сбора. Устаревшие записи могут создать ложную цепочку.','Приоритизируй связи, ведущие к администраторам и чувствительным системам, затем ищи минимальное изменение без потери работы сервиса.','Короткий путь в графе не равен готовой атаке: могут существовать дополнительные технические и организационные ограничения.'] }),

  B({ id:'telemetry', path:'defense', title:'Телеметрия: что нужно видеть', brief:'Логи, процессы, сеть и синхронизация времени как единая картина.', concept:'Один источник редко показывает весь инцидент. Журналы входа, событий службы, процессов, сетевых соединений и изменений файлов дополняют друг друга. Синхронизированное время позволяет собрать их в последовательность. Планируйте сбор заранее, до расследования.', command:'journalctl --since "1 hour ago" -p warning | head', meaning:'Посмотреть предупреждения своей Linux-машины за последний час.', output:'Oct 27 ... warning ...', flow:['События хоста','Время и корреляция','Гипотеза инцидента'], quiz:['Зачем синхронизировать время журналов?','Чтобы строить верную последовательность событий','Чтобы увеличить диск','Чтобы убрать DNS',0], tags:['logging','journalctl','siem','timeline'], notes:['Запись события должна отвечать на вопросы кто, что, где и когда, при этом не раскрывать лишние секреты.','Сравни события Linux-журнала с сетевыми данными и изменениями конфигурации для одного периода.','Отсутствие записи не доказывает отсутствия действия: источник мог не собирать событие или журнал мог быть повреждён.'] }),
  B({ id:'arp-detection', path:'defense', title:'Обнаружение аномалий локальной сети', brief:'Сравнение ARP, DHCP и сетевых наблюдений.', concept:'Подозрительная смена соответствия IP↔MAC — сигнал для проверки, особенно если речь о шлюзе. Сопоставьте его с DHCP, журналами коммутатора, переездом виртуальной машины и запланированными работами. Защитные механизмы на сетевом оборудовании полезны, если настроены под реальную топологию.', command:'ip neigh show; ip route | head', meaning:'Сравнить таблицу соседей и адрес шлюза на собственном хосте.', output:'192.0.2.1 lladdr ...\ndefault via 192.0.2.1', flow:['Изменение записи','Сопоставление источников','Подтверждение/опровержение'], quiz:['Достаточна ли одна изменившаяся ARP-запись для вывода об атаке?','Нет, нужен контекст','Да, всегда','Только при IPv6',0], tags:['arp','detection','dhcp','switch'], notes:['Смена MAC может быть нормальной при отказоустойчивости или миграции ВМ; базовая линия уменьшает ложные тревоги.','Наблюдай не только факт изменения, но и его время, частоту, устройства и последствия для маршрута.','ARP не работает через маршрутизатор, поэтому эта проверка описывает только локальный сегмент.'] }),
  B({ id:'server-hardening', path:'defense', title:'Укрепление Linux-сервера', brief:'Обновления, доступ, службы и проверка результата.', concept:'Укрепление — последовательное уменьшение ненужной поверхности: обновления, минимальные пакеты, ограничение привилегий, безопасный SSH, firewall и журналы. Изменяйте по одному шагу с планом отката и проверяйте работающий сервис после каждого изменения.', command:'sudo apt list --upgradable; systemctl --type=service --state=running', meaning:'Инвентаризация обновлений и работающих служб на своей Debian/Kali-системе.', output:'Listing...\nssh.service loaded active running', flow:['Инвентаризация','Минимальные изменения','Проверка / откат'], quiz:['Как безопаснее менять удалённый сервер?','Пошагово с откатом и проверкой','Сразу отключить всё','Удалить журналы',0], tags:['hardening','ssh','firewall','updates'], notes:['Начинай с бизнес-назначения сервера: какие сервисы и пользователи действительно нужны.','После ограничения сети проверь доступ с ожидаемых источников и резервный канал администрирования.','Один чек-лист не подходит всем серверам: безопасность оценивается вместе с доступностью и задачей системы.'] }),
  B({ id:'incident-timeline', path:'defense', title:'Линия времени инцидента', brief:'Свяжи события в причинную историю без поспешных выводов.', concept:'Расследование строится как временная шкала: первое наблюдение, изменения учётных записей, запуск процессов, сетевые связи и реакция. Каждое событие должно иметь источник и уверенность. Временная корреляция полезна, но сама по себе не доказывает причинность.', command:'journalctl --output=short-iso --since "2026-10-27 09:00" | head', meaning:'Посмотреть формат временных меток в собственном журнале.', output:'2026-10-27T09:00:01+04:00 host service: ...', flow:['Сбор событий','Нормализация времени','Проверка гипотез'], quiz:['Достаточно ли близости событий по времени для доказательства причины?','Нет','Да','Только в Wireshark',0], tags:['forensics','timeline','journalctl','evidence'], notes:['Нормализуй часовые пояса и отмечай возможный дрейф часов, прежде чем объединять данные разных узлов.','Фиксируй неизменяемые копии исходных журналов и работай с рабочими копиями, если требуется сохранить доказательства.','У некоторых событий время записи отличается от времени самого действия; учитывай задержку доставки журналов.'] }),
  B({ id:'response-cycle', path:'defense', title:'Реакция и восстановление', brief:'Изоляция, сохранение доказательств, исправление и контроль.', concept:'При подозрении на инцидент важно одновременно ограничить распространение и сохранить сведения для понимания причины. План определяет ответственных, каналы связи, критерии изоляции и восстановления. После исправления нужно наблюдать систему и проверить, что исходный путь риска закрыт.', command:'printf "обнаружить → ограничить → исследовать → восстановить → проверить\n"', meaning:'Мнемоника этапов без выполнения действий на системе.', output:'обнаружить → ограничить → исследовать → восстановить → проверить', flow:['Обнаружение','Сдерживание и анализ','Восстановление'], quiz:['Что следует после технического исправления?','Проверка и наблюдение','Удаление отчёта','Игнорирование причины',0], tags:['incident response','recovery','containment'], notes:['Действие «выключить сервер» может уничтожить данные в памяти и повлиять на бизнес-процессы; решение принимается по плану.','Для восстановления важны чистые копии, доверенные образы, смена затронутых секретов и контроль доступа.','Возврат сервиса в сеть без устранения причины может привести к повторению инцидента.'] }),
  B({ id:'pentest-deliverable', path:'defense', title:'От технической находки к улучшению', brief:'Как результат проверки становится конкретной задачей для команды.', concept:'Отчёт должен объяснять воздействие на конкретный актив, условия воспроизведения, доказательство и реалистичное исправление. Разделяйте факт, вероятность и допущения. После исправления ретест проверяет исходный сценарий и возможные побочные эффекты.', command:'printf "факт | влияние | исправление | ретест\n"', meaning:'Четыре опорные части краткой карточки находки.', output:'факт | влияние | исправление | ретест', flow:['Факт','Действие владельца','Повторная проверка'], quiz:['Что делает рекомендацию полезной?','Конкретное исправление и критерий проверки','Только высокий балл','Большой объём текста',0], tags:['report','remediation','retest','risk'], notes:['Пиши так, чтобы владелец без доступа к твоей голове понял, что изменить и как убедиться в результате.','Согласуй срочность с контекстом: доступность, чувствительность данных, влияние на процессы и компенсирующие меры.','Инструмент может ошибиться; в отчёт попадают только подтверждённые наблюдения с обозначенными ограничениями.'] }),
];
